from cuerpo import cuotas as _cuo
monkeypatch.setattr(_cuo, "RUTA", str(tmp_path / "CUOTAS.json"))
# Ninguna prueba llama a un cerebro de verdad (ley 23; medido 2026-09-22, orden 53: 16 rojas en 370 s).
# Las tres vigias del enchufe falsifican por dentro y siguen igual; las que falsifican preguntar
# a su manera siguen igual porque su monkeypatch va despues.
_PRUEBAN_EL_ENCHUFE = (
    "test_vigia_bigpickle_enchufe.py",
    "test_vigia_la_pieza_que_le_pregunta_a_codex.py",
    "test_vigia_el_enchufe_de_grok.py",
)
if request.node.fspath.basename not in _PRUEBAN_EL_ENCHUFE:
    def _preguntar_falso(*args, **kwargs):
        return ("", ["en las pruebas no se llama a un cerebro de verdad"])
    for _nombre in ("bigpickle", "grok", "codex"):
        try:
            _mod = __import__(f"cuerpo.{_nombre}", fromlist=["preguntar"])
        except Exception:
            continue
        monkeypatch.setattr(_mod, "preguntar", _preguntar_falso)
yield

